import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"63、【既濟】 離下坎上","description":"橫渠易說 - 63、【既濟】 離下坎上","frontmatter":{"title":"63、【既濟】 離下坎上","description":"橫渠易說 - 63、【既濟】 離下坎上"},"headers":[],"relativePath":"classics/hengqu/065.md","filePath":"classics/hengqu/065.md"}'),l={name:"classics/hengqu/065.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_63、【既濟】-離下坎上" tabindex="-1">63、【既濟】 離下坎上 <a class="header-anchor" href="#_63、【既濟】-離下坎上" aria-label="Permalink to “63、【既濟】 離下坎上”">​</a></h1><h3 id="彖曰-既濟亨-小者亨也-利貞-剛柔正而位當也。-初吉-柔得中也-終止則亂-其道窮也。" tabindex="-1">彖曰：“既濟亨”，小者亨也，“利貞”，剛柔正而位當也。“初吉”，柔得中也；終止則亂，其道窮也。 <a class="header-anchor" href="#彖曰-既濟亨-小者亨也-利貞-剛柔正而位當也。-初吉-柔得中也-終止則亂-其道窮也。" aria-label="Permalink to “彖曰：“既濟亨”，小者亨也，“利貞”，剛柔正而位當也。“初吉”，柔得中也；終止則亂，其道窮也。”">​</a></h3><h3 id="象曰-水在火上-既濟-君子以思患而豫防之。" tabindex="-1">象曰：水在火上，既濟，君子以思患而豫防之。 <a class="header-anchor" href="#象曰-水在火上-既濟-君子以思患而豫防之。" aria-label="Permalink to “象曰：水在火上，既濟，君子以思患而豫防之。”">​</a></h3><p>通其變然後可久，故止則亂也。</p><h3 id="初九-曳其輪-濡其尾-無咎。-象曰-曳其輪-義無咎也。" tabindex="-1">初九，曳其輪，濡其尾，無咎。 象曰：“曳其輪”，義無咎也。 <a class="header-anchor" href="#初九-曳其輪-濡其尾-無咎。-象曰-曳其輪-義無咎也。" aria-label="Permalink to “初九，曳其輪，濡其尾，無咎。 象曰：“曳其輪”，義無咎也。”">​</a></h3><h3 id="六二-婦喪其茀勿逐-七日得。-象曰-七日得-以中道也。" tabindex="-1">六二，婦喪其茀勿逐，七日得。 象曰：“七日得”，以中道也。 <a class="header-anchor" href="#六二-婦喪其茀勿逐-七日得。-象曰-七日得-以中道也。" aria-label="Permalink to “六二，婦喪其茀勿逐，七日得。 象曰：“七日得”，以中道也。”">​</a></h3><h3 id="九三-高宗伐鬼方-三年克之-小人勿用。-象曰-三年克之-憊也。" tabindex="-1">九三，高宗伐鬼方，三年克之，小人勿用。 象曰：“三年克之”，憊也。 <a class="header-anchor" href="#九三-高宗伐鬼方-三年克之-小人勿用。-象曰-三年克之-憊也。" aria-label="Permalink to “九三，高宗伐鬼方，三年克之，小人勿用。 象曰：“三年克之”，憊也。”">​</a></h3><p>上六險而應，此處卦之未濟以終亂者也，故以比鬼方。九三以陽居陽，文明而正，故用師雖久，困而必克，小人用之，取亡之道也。</p><h3 id="六四-繻有衣袽-終日戒。-象曰-終日戒-有所疑也。" tabindex="-1">六四，繻有衣袽，終日戒。 象曰：“終日戒”，有所疑也。 <a class="header-anchor" href="#六四-繻有衣袽-終日戒。-象曰-終日戒-有所疑也。" aria-label="Permalink to “六四，繻有衣袽，終日戒。 象曰：“終日戒”，有所疑也。”">​</a></h3><h3 id="九五-東鄰殺牛-不如西鄰之禴祭實受其福。-象曰-東鄰殺牛-不如西鄰之時也。-實受其福-吉大來也。" tabindex="-1">九五，東鄰殺牛，不如西鄰之禴祭實受其福。 象曰：“東鄰殺牛”，不如西鄰之時也。“實受其福”，吉大來也。 <a class="header-anchor" href="#九五-東鄰殺牛-不如西鄰之禴祭實受其福。-象曰-東鄰殺牛-不如西鄰之時也。-實受其福-吉大來也。" aria-label="Permalink to “九五，東鄰殺牛，不如西鄰之禴祭實受其福。 象曰：“東鄰殺牛”，不如西鄰之時也。“實受其福”，吉大來也。”">​</a></h3><p>東鄰，上六也；西鄰，六四也。過於濟，厚也；幾於中，時也。濟而合禮，雖薄受福。九五既濟之主，舉上與下，其義之得不言而著也。</p><h3 id="上六-濡其首-厲。-象曰-濡其首-厲-何可久也" tabindex="-1">上六，濡其首，厲。 象曰：“濡其首，厲”，何可久也! <a class="header-anchor" href="#上六-濡其首-厲。-象曰-濡其首-厲-何可久也" aria-label="Permalink to “上六，濡其首，厲。 象曰：“濡其首，厲”，何可久也!”">​</a></h3>',12)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
